def count_tokens(src, model='cl100k_base'):
    "Count tokens in `src` using `model` encoding"
    return len(tiktoken.get_encoding(model).encode(src))

# %% ../nbs/00_dutil.ipynb #b501510f
async def ctxusage(fromid:str='', toid:str='', dname:str='', msgs=None):
    "Estimate tokens in non-skipped dialog messages between `fromid` and `toid`"
    if msgs is None: msgs = await find_msgs(include_output=True, include_skipped=True, dname=dname)
    ids = [m['id'] for m in msgs]
    start = ids.index(fromid) if fromid else 0
    toid = toid or (await read_msg(0, dname=dname))['id']
    end = ids.index(toid)
    src = '\n'.join(f"{m['content']}\n{m.get('output') or ''}" for m in msgs[start:end] if not m['skipped'])
    return int(count_tokens(src)*1.25)

# %% ../nbs/00_dutil.ipynb #087e1b95
def _strip_tok(s):
    for info,_,start,end in reversed(fenced_blocks(s)):
        if info == 'json {.usage}': s = s[:start].rstrip() + s[end:]
    return s

async def strip_token_usage(m, dname=''):
    "Remove Solveit token usage annotation from the output of a message `m`"
    if m.msg_type=='prompt':
        await update_msg(m.id, dname=dname, output=_strip_tok(m.output))

# %% ../nbs/00_dutil.ipynb #0a15d831
async def strip_ctx_usage(dname=''):
    "Remove Solveit token usage annotation from all messages output, and return the old/total token count"
    b = await ctxusage(dname=dname)
    ms = await find_msgs(msg_type='prompt', include_meta=False, trunc_in=True, include_skipped=True, dname=dname)
    for m in ms: await strip_token_usage(m, dname)
    a = await ctxusage(dname=dname)
    return f'{b} → {a} ({a/b:.1%})'

